{
  "findings": [
    {
      "title": "Inconsistent PK sampling times: Day 8 PK collected ±1 day conflicts with 10% window for 4-hour sample (±24 min)",
      "page": 27,
      "quote": "Day 8 PK is to be collected ±1 day.",
      "severity": "major"
    },
    {
      "title": "Contradictory dosing instructions: 'AMG 510 should not be taken 2 hours before the dosing time' is unclear and conflicts with 'not be taken 6 hours after the dosing time'",
      "page": 26,
      "quote": "AMG 510 should not be taken 2 hours before the dosing time; in the event not possible, AMG 510 should not be taken 6 hours after the dosing time (based on the previous day’s dose).",
      "severity": "major"
    },
    {
      "title": "Inconsistent imaging schedule: Table says imaging every 6 weeks from C1D1 (weeks 7, 13, ...) but footnote says imaging until independent central confirmation of progression, which may be earlier",
      "page": 27,
      "quote": "Imaging every 6 weeks from cycle 1 day 1 (± 7 days) (at weeks 7, 13, 19, 25, 31, 37, 43, and 49), and then at 9-week intervals (± 7 days) thereafter",
      "severity": "minor"
    },
    {
      "title": "Inconsistent LTFU duration: Footnote says LTFU is 5 years after last subject enrolled, but text says 'LTFU will be 5 years after last subject enrolled' – no contradiction but missing start point for individual subjects",
      "page": 30,
      "quote": "LTFU will be 5 years after last subject enrolled, or until withdrawal of consent, loss to follow-up, or subject death, whichever occurs first.",
      "severity": "minor"
    },
    {
      "title": "Missing information: No sample size or randomization ratio provided in the excerpt",
      "page": 25,
      "quote": "Protocol Number: 20190009",
      "severity": "critical"
    },
    {
      "title": "Missing information: No primary endpoint or statistical analysis section referenced in the excerpt",
      "page": 25,
      "quote": "Protocol Number: 20190009",
      "severity": "critical"
    },
    {
      "title": "Inconsistent PRO assessment schedule: PGIC collected at cycle 3 and 5, but PGIS at cycles 1, 3, 5 – no baseline for PGIC",
      "page": 29,
      "quote": "PGIC will be collected in the clinic on day 1 of cycles 3 and cycle 5 (no collection needed at screening or cycle 1 for PGIC).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent thyroid function testing: Table shows thyroid function tests at screening and day 1 of each cycle, but note says 'pre-dose on day 1 of each cycle (except cycle 1)' – cycle 1 day 1 is not pre-dose?",
      "page": 25,
      "quote": "Thyroid function testing at screening, pre-dose on day 1 of each cycle (except cycle 1), at the end of treatment, and at safety follow-up.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent cholesterol/triglyceride schedule: Table shows (X) at cycle 5+ but note says every other cycle (1,3,5,7) – cycle 5 is included, but table only shows (X) at cycle 5+ column, not specific cycles",
      "page": 26,
      "quote": "Cholesterol and triglyceride levels on pre-dose on day 1 of every other cycle (ie, cycle 1, 3, 5, 7, etc).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent docetaxel schedule: Table shows docetaxel administered on day 1 of each cycle, but footnote says 'every 3 weeks ± 3 days' – cycle length is 21 days, so 3 weeks is consistent, but no day 8 dosing for docetaxel?",
      "page": 32,
      "quote": "Docetaxel will be administered every 3 weeks ± 3 days until independent central confirmation of progression",
      "severity": "minor"
    },
    {
      "title": "Inconsistent crossover details: Footnote e for AMG 510 says 'See Section 8.1.6 for treatment beyond radiologic progression' but footnote e for docetaxel says 'See Section 8.1.7' – cross-reference mismatch",
      "page": 30,
      "quote": "See Section 8.1.6 for treatment beyond radiologic progression.",
      "severity": "major"
    },
    {
      "title": "Inconsistent tumor assessment footnote: For AMG 510, footnote f says 'Subjects that undergo treatment beyond progression or crossover, from docetaxel to AMG 510, will continue to receive scans after confirmation of first PD.' but for docetaxel it says 'Subjects that undergo treatment beyond progression or crossover will continue to receive scans' – missing 'from docetaxel to AMG 510' but that's minor",
      "page": 30,
      "quote": "Subjects that undergo treatment beyond progression or crossover, from docetaxel to AMG 510, will continue to receive scans after confirmation of first PD.",
      "severity": "minor"
    }
  ]
}
